import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] x = new int[6];
        int total = 0;
        for (int i = 0; i < 6; i++) {
            x[i] = sc.nextInt();
            total += x[i];
        }

        if (total % 3 != 0) {
            System.out.println("N");
            return;
        }

        int target = total / 3;
        boolean possible = false;

        // O andar do topo precisa de 1 cubo com peso igual a target
        for (int top = 0; top < 6; top++) {
            if (x[top] == target) {
                // O segundo andar precisa de 2 cubos que somam target
                for (int i = 0; i < 6; i++) {
                    if (i == top) continue;
                    for (int j = i + 1; j < 6; j++) {
                        if (j == top) continue;
                        if (x[i] + x[j] == target) {
                            possible = true;
                            break;
                        }
                    }
                    if (possible) break;
                }
            }
            if (possible) break;
        }

        if (possible) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
